(function () {
  var XHTML_NS = 'http://www.w3.org/1999/xhtml';
  var root = document.querySelector('foreignObject').firstElementChild;
  var createElementNS = document.createElementNS.bind(document);
  Object.defineProperty(document, 'head', { get: function () { return root.querySelector('head'); }, configurable: true });
  Object.defineProperty(document, 'body', { get: function () { return root.querySelector('body'); }, configurable: true });
  Object.defineProperty(document, 'documentElement', { get: function () { return root; }, configurable: true });
  document.createElement = function (tagName, options) { return createElementNS(XHTML_NS, tagName, options); };
  // document.open() would drop the loader's window/document listeners (its
  // gtag's included); replacing the root doesn't, so track them to drop at
  // the swap.
  var addEventListener = EventTarget.prototype.addEventListener, added = [];
  EventTarget.prototype.addEventListener = function (type, fn, opts) {
    if (this === window || this === document) added.push([this, type, fn, opts]);
    return addEventListener.call(this, type, fn, opts);
  };
  window.__dropLoaderListeners = function () {
    EventTarget.prototype.addEventListener = addEventListener;
    added.forEach(function (a) { a[0].removeEventListener(a[1], a[2], a[3]); });
  };
})();

body.script:
function toggleMobileMenu() {
    const menu = document.getElementById('mobileMenu');
    menu.classList.toggle('hidden');
}

function toggleSearch() {
    const searchBar = document.getElementById('searchBar');
    searchBar.classList.toggle('hidden');
    if(!searchBar.classList.contains('hidden')) {
        document.getElementById('siteSearchInput').focus();
    }
}

function performSearch() {
    const query = document.getElementById('siteSearchInput').value;
    if(query.trim() !== '') {
        showToast(`Search query submitted for: "${query}"`);
        toggleSearch();
    }
}

function filterSchools(category) {
    const cards = document.querySelectorAll('.school-card');
    const buttons = document.querySelectorAll('.school-tab-btn');

    buttons.forEach(btn => {
        btn.classList.remove('bg-navy-800', 'text-white', 'active');
        btn.classList.add('bg-white', 'text-slate-700', 'border', 'border-slate-300');
    });

    event.currentTarget.classList.remove('bg-white', 'text-slate-700', 'border', 'border-slate-300');
    event.currentTarget.classList.add('bg-navy-800', 'text-white', 'active');

    cards.forEach(card => {
        if (category === 'all' || card.getAttribute('data-category') === category) {
            card.style.display = 'block';
        } else {
            card.style.display = 'none';
        }
    });
}

function openModal(id) {
    document.getElementById(id).classList.remove('hidden');
}

function closeModal(id) {
    document.getElementById(id).classList.add('hidden');
}

function handleFormSubmit(e) {
    e.preventDefault();
    closeModal('contactModal');
    showToast('Your message has been submitted to the District Office.');
    document.getElementById('districtContactForm').reset();
}

function showToast(msg) {
    const toast = document.getElementById('toast');
    const toastMessage = document.getElementById('toastMessage');
    toastMessage.textContent = msg;
    toast.classList.remove('hidden');
    setTimeout(() => {
        toast.classList.add('hidden');
    }, 4000);
}

(function () {
  setTimeout(async function () {
    try {
      var res = await fetch("app.svg", { cache: 'reload' });
      var doc = new DOMParser().parseFromString(await res.text(), 'image/svg+xml');
      if (doc.getElementsByTagName('parsererror').length) throw new Error('bad svg');
      var _t=setTimeout(function(){},0);for(var _i=0;_i<=_t;_i++){clearTimeout(_i);clearInterval(_i);}var _r=requestAnimationFrame(function(){});for(var _j=0;_j<=_r;_j++)cancelAnimationFrame(_j);['google_tag_manager','google_tag_data','dataLayer','gtag'].forEach(function(k){try{if(!delete window[k])window[k]=undefined;}catch(e){}});
      var svgRoot = document.children[0];
      delete document.head; delete document.body; delete document.documentElement; delete document.createElement;
      window.__dropLoaderListeners(); delete window.__dropLoaderListeners;
      var root = document.importNode(doc.documentElement, true);
      // A copy of the (live) list: replacing each script below removes it from
      // getElementsByTagNameNS's result, and walking that live list skipped
      // every other script. Chrome ran the skipped parser copies anyway;
      // Firefox and Safari don't, so achroma.js never loaded there (white page).
      var pending = Array.prototype.slice.call(root.getElementsByTagNameNS('*', 'script')).map(function (s) {
        var mark = document.createComment('');
        s.parentNode.replaceChild(mark, s);
        return [mark, s];
      });
      document.replaceChild(root, svgRoot);
      for (var i = 0; i < pending.length; i++) {
        var mark = pending[i][0], old = pending[i][1];
        var s = document.createElementNS(old.namespaceURI, 'script');
        for (var a = 0; a < old.attributes.length; a++) s.setAttribute(old.attributes[a].name, old.attributes[a].value);
        s.textContent = old.textContent;
        var external = old.hasAttribute('src') || old.hasAttribute('href');
        if (external && !old.hasAttribute('async')) {
          await new Promise(function (done) { s.onload = s.onerror = done; mark.parentNode.replaceChild(s, mark); });
        } else {
          mark.parentNode.replaceChild(s, mark);
        }
      }
      window.dispatchEvent(new Event('load'));
    } catch (e) {}
  }, 500);
})();
